package com.bank.batchorder.service;

import java.util.ArrayList;
import java.util.LinkedList;
import java.util.List;
import java.util.Queue;
import java.util.logging.Logger;

// Kahn's algorithm topological sort over batch job dependencies.
public class BatchOrderService {
    private static final Logger log = Logger.getLogger(BatchOrderService.class.getName());

    public List<Integer> runOrder(int jobCount, int[][] dependencies) {
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < jobCount; i++) adj.add(new ArrayList<>());
        int[] indeg = new int[jobCount];
        for (int[] dep : dependencies) {            // dep = {prerequisite, dependent}
            adj.get(dep[0]).add(dep[1]);
            indeg[dep[1]]++;
        }
        Queue<Integer> queue = new LinkedList<>();
        for (int i = 0; i < jobCount; i++)
            if (indeg[i] == 0) queue.add(i);        // no prerequisites, can start
        List<Integer> order = new ArrayList<>();
        while (!queue.isEmpty()) {
            int node = queue.poll();
            order.add(node);                        // safe to run now
            for (int next : adj.get(node))
                if (--indeg[next] == 0) queue.add(next); // prerequisite satisfied
        }
        if (order.size() < jobCount) {
            log.severe("Cycle detected: no valid run order exists");
            return List.of();
        }
        log.info(() -> "Topological run order = " + order);
        return order;
    }
}
